// The gate in front of the webhook, and the routing decision.
//
// Muse is expected to have done the watching and the writing already. This
// node's job is to refuse anything it should not publish, and to work out
// whether an image still has to be generated or one arrived with the request.
// It fails closed: no secret on the service means every call is refused.
const secret = String($env.MUSE_WEBHOOK_SECRET || '');
if (!secret) {
  throw new Error(
    'MUSE_WEBHOOK_SECRET is not set on the n8n service, so this webhook refuses every call. Set it in Coolify and redeploy.',
  );
}

const headers = $json.headers || {};
const given = String(headers['x-muse-secret'] || headers['x-webhook-secret'] || '');
const same =
  given.length === secret.length &&
  given.split('').reduce((acc, c, i) => acc + (c === secret[i] ? 0 : 1), 0) === 0;
if (!same) throw new Error('Refused: the x-muse-secret header was missing or did not match.');

const body = $json.body || {};
const message = String(body.message ?? body.text ?? body.caption ?? '').trim();
if (!message) {
  throw new Error('Refused: the body had no "message". Send {"message": "...", "image_prompt": "..."}.');
}
if (message.length > 63206) {
  throw new Error(`Refused: the message is ${message.length} characters and Facebook accepts 63206.`);
}

const link = String(body.link ?? body.url ?? '').trim();
if (link && !/^https:\/\/[^\s]+$/.test(link)) {
  throw new Error(`Refused: "link" must be a single https URL, got "${link.slice(0, 80)}".`);
}

// Either Muse describes the image and n8n generates it, or Muse sends the
// image itself. Both are accepted; one of them is required, because this
// workflow publishes a photo post and a photo post needs a photo.
const prompt = String(body.image_prompt ?? body.imagePrompt ?? body.scene ?? '').trim();
const supplied = String(body.image_base64 ?? body.imageBase64 ?? '').replace(/^data:image\/\w+;base64,/, '').trim();

if (!prompt && !supplied) {
  throw new Error('Refused: send either "image_prompt" for n8n to generate one, or "image_base64" with your own image.');
}
if (supplied && !/^[A-Za-z0-9+/=\s]+$/.test(supplied)) {
  throw new Error('Refused: "image_base64" is not base64.');
}
if (supplied && supplied.length < 2000) {
  throw new Error(`Refused: "image_base64" decodes to about ${Math.round((supplied.length * 3) / 4)} bytes, which is too small to be a real image.`);
}
if (prompt && prompt.length > 30000) {
  throw new Error('Refused: "image_prompt" is longer than the image API accepts.');
}

return [
  {
    json: {
      origin: 'muse',
      topic: String(body.term ?? body.topic ?? body.headline ?? '').trim() || '(sent by Muse)',
      message,
      link,
      source: String(body.source ?? '').trim(),
      // A photo post does not render a link preview card the way a feed post
      // does, so the link has to be in the caption or it is not there at all.
      fbMessage: link ? `${message}\n\n${link}` : message,
      imagePrompt: prompt,
      imageBase64: supplied,
      // Drives the IF that follows: generate, or use what arrived.
      needsGenerating: !supplied && !!prompt,
    },
  },
];

// GPT image models always return base64: response_format is deprecated and
// unsupported for them, and the DALL-E models that could return a URL are
// retired. So there is no hosted-URL option to fall back on, and this node
// exists to pull the base64 out and refuse anything that is not an image.
const body = $json.body;
const b64 = body && body.data && body.data[0] ? body.data[0].b64_json : '';

if (!b64) {
  const why = (body && body.error && body.error.message) || JSON.stringify(body || {}).slice(0, 300);
  throw new Error(`Image generation returned nothing: ${why}`);
}
// An empty or truncated image uploads as a broken photo post, which is worse
// than no post at all, so this fails rather than publishing it.
if (b64.length < 5000) {
  throw new Error(`Image generation returned about ${Math.round((b64.length * 3) / 4)} bytes, which is too small to be a real image.`);
}

const src = $('Check what Muse sent').item.json;
return [{ json: { ...src, imageBase64: b64, imageBytes: Math.round((b64.length * 3) / 4), imageFrom: 'generated' } }];

// Muse sent the image itself. Nothing to generate; normalise the item so both
// routes hand the same shape to the file conversion that follows.
const src = $json;
return [
  {
    json: {
      ...src,
      imageBytes: Math.round((String(src.imageBase64 || '').length * 3) / 4),
      imageFrom: 'sent by Muse',
    },
  },
];

// A photo post answers with a photo id and, when it reaches the Page's feed,
// a post_id as well. Facebook also answers 200 with an error object in the
// body, so the status code on its own is not proof that anything was
// published: the post counts as landed only when an id comes back.
const res = $json || {};
const body = res.body || {};
const status = Number(res.statusCode || 0);
const photoId = body.id ? String(body.id) : '';
const postId = body.post_id ? String(body.post_id) : '';
const landed = status >= 200 && status < 300 && !!photoId && !body.error;

// Whichever route ran. Calling $() on a node that did not execute throws.
let src = null;
for (const name of ['Take the generated image', 'Use the image Muse sent']) {
  try {
    const j = $(name).first().json;
    if (j && j.message) {
      src = j;
      break;
    }
  } catch (e) {
    /* that route did not run */
  }
}
src = src || { topic: '(unknown)', message: '', link: '', imageFrom: 'unknown', imageBytes: 0 };

const reason = landed
  ? ''
  : body.error
    ? `Facebook refused it: ${body.error.message || JSON.stringify(body.error)}`
    : `Facebook answered ${status || 'nothing'} with no photo id. Body: ${JSON.stringify(body).slice(0, 400)}`;

return [
  {
    json: {
      landed,
      failed: !landed,
      topic: src.topic,
      imageFrom: src.imageFrom,
      imageBytes: src.imageBytes,
      photoId,
      postId,
      permalink: postId ? `https://www.facebook.com/${postId}` : '',
      link: src.link || '',
      message: src.message,
      reason,
    },
  },
];

